import io,re
p='CHANTIERS.md'; L=io.open(p,encoding='utf-8').read().rstrip('\n').split('\n')
def maj(num, etat=None, avant=None, juge=None, lot=None):
    for i,l in enumerate(L):
        if re.match(r'^\| %s \|' % re.escape(num), l):
            c=l.strip()[2:-2].split(' | '); assert len(c)==7,(num,len(c))
            if etat: c[3]=etat
            if avant: c[4]=avant if c[4].strip() in ('—','') else avant+' '+c[4]
            if juge: c[5]=juge
            if lot: c[6]=lot
            L[i]='| '+' | '.join(c)+' |'; return
    raise SystemExit(num)
